import re
from datetime import date
from decimal import Decimal
from collections import defaultdict

SRC = r"C:\Users\<user>\AppData\Local\Temp\prompt-evals-session-ytaoem2f\personal_expenses.txt"
YEAR = 2026
MONTHS = {m: i for i, m in enumerate(['jan', 'feb', 'mar', 'apr', 'may', 'jun',
                                      'jul', 'aug', 'sep', 'oct', 'nov', 'dec'], 1)}

DATE_RES = [
    ('iso', re.compile(r'(?<!\d)(\d{4})-(\d{2})-(\d{2})(?!\d)')),
    ('word', re.compile(r'\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?!\d)', re.I)),
    ('slash', re.compile(r'(?<![\d/])(\d{1,2})/(\d{1,2})(?:/(\d{4}|\d{2}))?(?![\d/])')),
    ('mmdd', re.compile(r'(?<![\d-])(\d{2})-(\d{2})(?![\d-])')),
]
AMT_RE = re.compile(r'(-?)\$?(-?)(\d[\d,]*\.\d{2})(?!\d)')

CATEGORIES = [
    ('Uncategorized (transfer/cash)', r'zelle|paypal|atm cash|venmo'),
    ('Bills & subscriptions', r'icloud|amazon prime|netflix|spotify premium|xfinity|verizon'),
    ('Health & fitness', r'riverside physical|walgreens|\bcvs\b|dr\. hensley|planet fitness'),
    ('Entertainment', r'spotify concert|\bamc\b|ticketmaster|bowl-o-rama|steam'),
    ('Travel', r'delta air|marriott|hertz|airport parking'),
    ('Groceries', r'trader joe|\baldi\b|kroger|costco|whole foods'),
    ('Eating out & coffee', r'coffee|starbucks|chipotle|panera|mcdonald|sushi kame|thai orchid|luigi|rustic tap|bagel corner'),
    ('Gas & transport', r'\bshell\b|chevron|\bbp gas|jiffy lube|\blyft\b|\buber\b|city parking'),
    ('Shopping', r'amazon|best buy|\btarget\b|\brei\b|old navy|ikea|barnes|home depot|return processed'),
]


def clean(t):
    t = re.sub(r'[|()]', ' ', t)
    t = re.sub(r'\s+', ' ', t).strip()
    return re.sub(r'^[\s\-,:]+|[\s\-,:]+$', '', t)


def parse_line(text):
    s = re.sub(r'^\s*-\s*', '', text.strip())
    amts = list(AMT_RE.finditer(s))
    if not amts:
        return None, 'no amount'
    m = amts[-1]
    amount = Decimal(m.group(3).replace(',', ''))
    if m.group(1) == '-' or m.group(2) == '-':
        amount = -amount
    rest = s[:m.start()] + ' ' + s[m.end():]
    hits = [(kind, dm) for kind, rx in DATE_RES for dm in rx.finditer(rest)]
    if len(hits) != 1:
        return None, f'{len(hits)} date matches'
    kind, dm = hits[0]
    if kind == 'iso':
        y, mo, d = int(dm.group(1)), int(dm.group(2)), int(dm.group(3))
    elif kind == 'word':
        y, mo, d = YEAR, MONTHS[dm.group(1)[:3].lower()], int(dm.group(2))
    elif kind == 'slash':
        y = YEAR
        if dm.group(3):
            y = int(dm.group(3))
            y = y + 2000 if y < 100 else y
        mo, d = int(dm.group(1)), int(dm.group(2))
    else:
        y, mo, d = YEAR, int(dm.group(1)), int(dm.group(2))
    try:
        when = date(y, mo, d)
    except ValueError:
        return None, 'invalid date'
    merchant = clean(rest[:dm.start()] + ' ' + rest[dm.end():])
    if not merchant:
        return None, 'no merchant'
    return {'date': when, 'merchant': merchant, 'amount': amount}, None


def categorize(merchant):
    for name, pat in CATEGORIES:
        if re.search(pat, merchant, re.I):
            return name
    return None


def money(x):
    return f"${x:,.2f}" if x >= 0 else f"-${-x:,.2f}"


with open(SRC, encoding='utf-8') as f:
    raw = f.read().splitlines()

records, failures = [], []
for ln, text in enumerate(raw, 1):
    if ln <= 3 or not text.strip():
        continue
    rec, err = parse_line(text)
    if err:
        failures.append((ln, text, err))
        continue
    rec['line'] = ln
    rec['raw'] = text.strip()
    rec['cat'] = categorize(rec['merchant'])
    records.append(rec)

print(f"Transaction lines in file: {sum(1 for i, t in enumerate(raw, 1) if i > 3 and t.strip())}")
print(f"Parsed: {len(records)}   Failed: {len(failures)}")
for ln, text, err in failures:
    print(f"  FAIL line {ln} ({err}): {text}")
print("Lines with no category rule match:")
for r in records:
    if r['cat'] is None:
        print(f"  line {r['line']}: {r['merchant']}")

seen = {}
for r in records:
    k = (r['date'], r['merchant'].lower(), r['amount'])
    r['dup'] = k in seen
    seen.setdefault(k, r['line'])

print("\nExact duplicates (same date, merchant, amount) -> excluded from totals:")
for r in records:
    if r['dup']:
        print(f"  line {r['line']} duplicates line {seen[(r['date'], r['merchant'].lower(), r['amount'])]}: {r['raw']}")

print("\nSame merchant + amount on different dates (check recurring vs duplicate):")
by_ma = defaultdict(list)
for r in records:
    by_ma[(r['merchant'].lower(), r['amount'])].append(r)
for (m, a), v in by_ma.items():
    if len(v) > 1:
        print(f"  {m} {money(a)}: lines {[x['line'] for x in v]} dates {[str(x['date']) for x in v]}")

print("\nSame merchant + date, different amounts:")
by_md = defaultdict(list)
for r in records:
    by_md[(r['merchant'].lower(), r['date'])].append(r)
for (m, d), v in by_md.items():
    if len(v) > 1:
        print(f"  {m} {d}: " + ", ".join(f"line {x['line']} {money(x['amount'])}" for x in v))

print("\nNegative amounts (refunds):")
for r in records:
    if r['amount'] < 0:
        print(f"  line {r['line']}: {r['date']} {r['merchant']} {money(r['amount'])} -> {r['cat']}")

print("\nUncategorized (transfer/cash):")
for r in records:
    if r['cat'] and r['cat'].startswith('Uncategorized'):
        print(f"  line {r['line']}: {r['date']} {r['merchant']} {money(r['amount'])}")

print("\nDates outside Jun-Aug 2026:")
for r in records:
    if r['date'].month not in (6, 7, 8) or r['date'].year != 2026:
        print(f"  line {r['line']}: {r['date']}")

tot = defaultdict(lambda: defaultdict(Decimal))
for r in records:
    if r['dup']:
        continue
    tot[r['cat']][r['date'].month] += r['amount']

MONTHS_USED = [6, 7, 8]
print("\nMonthly totals by category (after dedupe, refunds netted):")
print(f"{'Category':<32}{'Jun':>12}{'Jul':>12}{'Aug':>12}{'Total':>12}")
cats = sorted(tot.keys(), key=lambda c: -sum(tot[c].values()))
for c in cats:
    row = [tot[c][m] for m in MONTHS_USED]
    print(f"{str(c):<32}" + "".join(f"{money(x):>12}" for x in row) + f"{money(sum(row)):>12}")
grand = [sum(tot[c][m] for c in tot) for m in MONTHS_USED]
print(f"{'TOTAL':<32}" + "".join(f"{money(x):>12}" for x in grand) + f"{money(sum(grand)):>12}")

BUDGET = {'Eating out & coffee': Decimal(260), 'Shopping': Decimal(1200)}
print("\nBudget comparison:")
for c, target in BUDGET.items():
    print(f"  {c} (target {money(target)}/month)")
    for m in MONTHS_USED:
        spent = tot[c][m]
        print(f"    {m:>2}: spent {money(spent):>12}  diff {money(spent - target):>12}  {spent / target * 100:6.1f}% of target")

print("\nMonth-over-month changes by category (sorted by absolute $ change):")
changes = []
for c in tot:
    for a, b in [(6, 7), (7, 8)]:
        va, vb = tot[c][a], tot[c][b]
        pct = f"{(vb - va) / va * 100:+.1f}%" if va != 0 else "n/a"
        changes.append((abs(vb - va), c, f"{MONTH_LABEL}" if False else f"{a}->{b}", va, vb, pct))
changes.sort(key=lambda x: -x[0])
for _, c, label, va, vb, pct in changes[:12]:
    print(f"  {str(c):<32} {label}: {money(va)} -> {money(vb)}  change {money(vb - va)} ({pct})")

print("\nLargest individual transactions by month:")
for m in MONTHS_USED:
    top = sorted([r for r in records if r['date'].month == m and not r['dup']], key=lambda r: -r['amount'])[:5]
    print(f"  month {m}: " + "; ".join(f"{r['merchant']} {money(r['amount'])} ({r['date']})" for r in top))

print("\nEating out & coffee transactions:")
for r in records:
    if r['cat'] == 'Eating out & coffee' and not r['dup']:
        print(f"  {r['date']} {r['merchant']:<28} {money(r['amount'])}")

